// Ambil body webhook asli + embedding dari respons OpenAI
const body = $('Webhook').first().json.body || {};
const emb = $json.data[0].embedding;
if (!Array.isArray(emb) || emb.length === 0) {
  throw new Error('embedding dari OpenAI tidak valid');
}
const vectorK = Number(body.vector_k) || 8;
const embStr = emb.join(',');
const query = `SELECT c.id, c.content, c.page_or_slide, c.section_title,
       d.id AS document_id, d.filename, d.file_type
  FROM chunks c JOIN documents d ON d.id = c.document_id
 WHERE c.is_outdated = FALSE AND d.status = 'completed'
 ORDER BY c.embedding <=> '[${embStr}]'::vector
 LIMIT ${vectorK}`;
return [{ json: { query }, pairedItem: { item: 0 } }];

const rows = $input.all().map((item) => item.json);
const labeled = rows.map((r, idx) => ({
  document_id: r.document_id,
  filename: r.filename,
  file_type: r.file_type,
  page_or_slide: r.page_or_slide ?? null,
  section_title: r.section_title ?? null,
  content: r.content,
  label: idx + 1,
}));
const context = labeled
  .map((r) => {
    let head = `[${r.label}] (File: ${r.filename}, ${r.file_type}`;
    if (r.page_or_slide != null) head += `, halaman/slide ${r.page_or_slide}`;
    if (r.section_title) head += `, Bagian: ${r.section_title}`;
    return head + `)\n${r.content}`;
  })
  .join('\n\n---\n\n');
return [{ json: { labeled, context }, pairedItem: { item: 0 } }];
